'use strict';
// TEST-030: a closed, in-memory design prototype. No application imports, network, media capture or storage.
const q=new URLSearchParams(location.search),screens=['home','chat','study','quiz','audio','review','life'],chatStates=['welcome','listening','thinking','speaking','correct','incorrect','offline','api-error'];
const demo={screen:screens.includes(q.get('screen'))?q.get('screen'):'home',theme:q.get('theme')==='dark'?'dark':'light',chatState:chatStates.includes(q.get('state'))?q.get('state'):'welcome',target:['nl','en','fr'].includes(q.get('target'))?q.get('target'):'nl',level:['A1.1','A1.2','A2.1'].includes(q.get('level'))?q.get('level'):'A1.1',scenario:'Знайомство',draft:'',messages:[],selected:null,checked:false,reviewOpen:false,playing:false,lifeReply:null,voice:true};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4z M12 6v15',home:'m3 10 9-7 9 7 M5 9v12h5v-7h4v7h5V9',chat:'M4 4h16v12H9l-5 5z M8 8h8m-8 4h5',back:'m14 5-7 7 7 7',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',sun:'M12 3v2m0 14v2M3 12h2m14 0h2 M6 6 1 1m10 10 1 1M6 18l1-1M17 7l1-1 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10z',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3m-4 0h8',sound:'M3 9h4l5-4v14l-5-4H3z M16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',send:'m3 3 19 9-19 9 4-9z M7 12h15',check:'m5 12 4 4L19 6',repeat:'M20 7h-6m6 0V1M4 17h6m-6 0v6 M20 7a9 9 0 0 0-15-3M4 17a9 9 0 0 0 15 3',pin:'M12 22s8-8 8-14A8 8 0 1 0 4 8c0 6 8 14 8 14z M15 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0',play:'m8 4 12 8-12 8z',pause:'M8 4v16m8-16v16',headphones:'M4 14v-3a8 8 0 0 1 16 0v3 M4 12h4v8H4z M16 12h4v8h-4z',star:'m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z',wifi:'M3 8a16 16 0 0 1 18 0 M6 12a10 10 0 0 1 12 0 M9 16a5 5 0 0 1 6 0 M12 20h.01',alert:'m12 3 10 18H2z M12 9v5m0 3v1',briefcase:'M8 6V3h8v3 M3 7h18v14H3z M3 13h18',shop:'M3 9h18l-2-6H5z M5 10v11h14V10 M9 21v-7h6v7',flag:'M5 22V2m0 1h14l-3 5 3 5H5'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const avatar=(emotion='welcome',size='')=>`<span class="lexi-avatar ${size} emotion-${emotion}" role="img" aria-label="Lexi — ${esc(({welcome:'привітання',listening:'уважно слухає',thinking:'міркує',speaking:'пояснює',success:'підтримує успіх',encourage:'підтримує після помилки'})[emotion]||emotion)}"></span>`;
const master=cls=>`<img class="lexi-master ${cls||''}" src="assets/lexi-master-proposal.webp" width="768" height="768" alt="Пропозиція Lexi: рудий кіт із зеленими очима, окулярами й темно-зеленою кофтою LerenBe">`;
const button=(label,action,cls='button',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const go=(screen,label,cls='button')=>button(label,'navigate',cls,`data-screen="${screen}" ${label.startsWith('<svg')?'aria-label="Повернутися на головну"':''}`);
const names={nl:'Нідерландська',en:'Англійська',fr:'Французька'};
const words={nl:{word:'hallo',example:'Hallo, ik ben Anastasia.',meaning:'Привіт, я Анастасія.',options:['Goedemorgen','hallo','Dank je wel','Alsjeblieft'],good:'Ik werk in België.',bad:'Ik werken in België.',hello:'Hallo! Hoe gaat het met je?'},en:{word:'hello',example:'Hello, I am Anastasia.',meaning:'Привіт, я Анастасія.',options:['Good morning','hello','Thank you','Please'],good:'I work in Belgium.',bad:'I works in Belgium.',hello:'Hello! How are you today?'},fr:{word:'bonjour',example:'Bonjour, je suis Anastasia.',meaning:'Привіт, я Анастасія.',options:['Bonne nuit','bonjour','Merci','Au revoir'],good:'Je travaille en Belgique.',bad:'Je travailler en Belgique.',hello:'Bonjour ! Comment vas-tu ?'}};
const current=()=>words[demo.target];
function targetSelect(id='target'){return `<label class="target-label"><span>Мова навчання</span><select id="${id}" data-select="target" aria-label="Мова навчання">${Object.entries(names).map(([key,name])=>`<option value="${key}" ${demo.target===key?'selected':''}>${name}</option>`).join('')}</select></label>`}
function levelSelect(){return `<label class="level-label"><span>Рівень</span><select data-select="level" aria-label="Рівень навчання">${['A1.1','A1.2','A2.1'].map(l=>`<option ${demo.level===l?'selected':''}>${l}</option>`).join('')}</select></label>`}
function themeButton(){return button(icon(demo.theme==='dark'?'sun':'moon'),'theme','icon-button',`aria-label="${demo.theme==='dark'?'Світла':'Темна'} тема" aria-pressed="${demo.theme==='dark'}"`)}
function nav(){return `<nav class="main-nav" aria-label="Основна навігація">${[['home','Головна','home'],['study','Навчання','book'],['chat','Lexi','chat'],['life','LIFE','pin']].map(([s,label,i])=>go(s,icon(i)+`<span>${label}</span>`,demo.screen===s?'nav-item active':'nav-item')).join('')}</nav>`}
function brand(){return `<a href="?screen=home&theme=${demo.theme}" class="brand" aria-label="LerenBe — головна"><span class="brand-symbol">${icon('book')}</span>LerenBe<span class="brand-version">3.0</span></a>`}
function shell(content){return `<div class="app-shell"><aside class="desktop-rail">${brand()}${nav()}<div class="rail-note">Learn languages.<br>Live in Belgium.<small>Візуальний прототип</small></div></aside><main id="mainContent" tabindex="-1">${content}</main><div class="mobile-nav">${nav()}</div></div>`}
function header(){return `<header class="app-header"><div class="mobile-brand">${brand()}</div>${targetSelect()}<div class="header-controls"><span class="level-pill">${demo.level}</span>${themeButton()}</div></header>`}
function home(){return shell(`${header()}<section class="greeting"><div class="greeting-copy"><span class="eyebrow">ПРИВІТ, Я LEXI</span><h1>Твій наступний крок —<br>ще більше впевненості.</h1><p>Я поруч. Почнімо з короткого уроку.</p></div>${master()}</section><div class="dashboard"><section class="continue-card"><div class="continue-art"><picture><source media="(min-width:768px)" srcset="../../app/img/home/home-hero-desktop.webp"><img src="../../app/img/home/home-hero-mobile.webp" alt="Затверджений HERO A/C: знайомство у Генті" width="1280" height="800"></picture><span>${icon('pin')}Gent, België</span></div><div class="continue-copy"><div class="card-meta"><span class="eyebrow">ПРОДОВЖИТИ НАВЧАННЯ</span><span>5–10 хв</span></div><h2>Знайомство.<br>Перші справжні розмови.</h2><p>${names[demo.target]} · ${demo.level} · Частина 2/5</p>${go('study','Продовжити урок '+icon('arrow'),'button primary')}</div></section><section class="progress-summary" aria-label="Прогрес навчання"><div><span class="eyebrow">ТВІЙ ПРОГРЕС</span><b>1 <small>/ 197 уроків</small></b></div><div class="progress-track" role="progressbar" aria-label="Демонстраційний прогрес курсу" aria-valuenow="1" aria-valuemin="0" aria-valuemax="197"><i></i></div><span class="xp-badge">${icon('star')}20 XP</span></section><section class="lexi-entry"><div>${avatar('welcome','medium')}<div><span class="eyebrow">ОДИН СПІВРОЗМОВНИК. БЕЗЛІЧ ТЕМ.</span><h2>Поговори з Lexi.</h2><p>Знайди слова для роботи й повсякденного життя.</p></div></div>${go('chat','Почати розмову '+icon('arrow'),'button secondary')}</section><section class="mode-section"><div class="section-title"><h2>Практикуй по-своєму.</h2><span>Навчальні режими</span></div><div class="mode-grid">${[['study','book','Study','Слово, переклад, приклад'],['quiz','check','Quiz','Перевір себе'],['audio','headphones','Audio','Послухай і зрозумій'],['review','repeat','Review','Повтори складне']].map(([s,i,title,sub])=>go(s,`<span class="mode-icon">${icon(i)}</span><span><b>${title}</b><small>${sub}</small></span>${icon('arrow')}`,'mode-card')).join('')}</div></section><section class="life-entry"><img src="assets/life-station-proposal.webp" width="960" height="1440" alt="Чернетка сцени LIFE: зустріч Anastasia й Annick на вокзалі" loading="lazy"><div><span class="eyebrow">LERENBE LIFE</span><h2>Мова для твого<br>життя в Бельгії.</h2><p>Вокзал. Знайомство. Перша розмова.</p>${go('life','Увійти в історію '+icon('arrow'),'button primary')}</div></section></div><p class="data-note">Демонстраційні 20 XP і прогрес показані лише для оцінки дизайну. Результати не зберігаються.</p>`)}
const statesLabels={welcome:'Welcome',listening:'Listening',thinking:'Thinking',speaking:'Speaking',correct:'Correct answer',incorrect:'Incorrect answer',offline:'Offline','api-error':'API error'};
const stateEmotion={welcome:'welcome',listening:'listening',thinking:'thinking',speaking:'speaking',correct:'success',incorrect:'encourage',offline:'encourage','api-error':'encourage'};
const stateText={welcome:'Готовий до розмови',listening:'Прослуховування · демо',thinking:'Lexi готує відповідь · демо',speaking:'Lexi озвучує · демо',correct:'Гарна відповідь',incorrect:'Спробуймо ще раз',offline:'Немає з’єднання · приклад','api-error':'Помилка відповіді · приклад'};
function scenarios(){return `<div class="scenario-list" aria-label="Сценарії розмови">${[['Знайомство','chat'],['На роботі','briefcase'],['У магазині','shop']].map(([s,i])=>button(icon(i)+`<span>${s}</span>`,'scenario',demo.scenario===s?'scenario active':'scenario',`data-scenario="${s}"`)).join('')}</div>`}
function message(text,who='lexi',kind=''){return `<article class="message ${who} ${kind}">${who==='lexi'?avatar(kind==='error'?'encourage':'speaking','small'):''}<div><span class="message-author">${who==='lexi'?'Lexi':'Ти'} <small>· демонстрація</small></span><p>${esc(text)}</p>${who==='lexi'?button(icon('sound'),'speak-demo','message-sound',`aria-label="Показати стан озвучення Lexi (демо)"`):''}</div></article>`}
function chatBody(){const w=current(),s=demo.chatState;let html='';
 if(s==='welcome'&&demo.messages.length)html=message(w.hello);
 else if(s==='welcome')html=`<div class="chat-welcome">${master()}<span class="eyebrow">ТВОЯ МОВА. ТВІЙ ТЕМП.</span><h1>Поговорімо?</h1><p>Я Lexi. Допоможу потренувати короткі розмови — від першого знайомства до робочого дня.</p><span class="mock-tag">Демо чат · відповіді заготовлені</span></div>`;
 else if(s==='listening')html=`<section class="live-state listening">${avatar('listening','large')}<h1>Я уважно слухаю.</h1><div class="voice-wave" aria-hidden="true">${'<i></i>'.repeat(19)}</div><p>Це демонстрація стану. Мікрофон не вмикається, аудіо не записується.</p>${button('Завершити демо прослуховування','stop-listening','button secondary')}</section>`;
 else {html=message(w.hello)+message(s==='incorrect'?w.bad:w.good,'user');
 if(s==='thinking')html+=`<div class="thinking-state" role="status">${avatar('thinking','medium')}<div><b>Lexi міркує</b><div class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></div><p>Демонстрація індикатора відповіді</p></div></div>`;
 if(s==='speaking')html+=message('Гарний початок! Повтори фразу повільно, а потім скажи її у своєму темпі.')+`<div class="speaking-state">${avatar('speaking','medium')}<div><b>Озвучення відповіді · демо</b><div class="voice-wave" aria-hidden="true">${'<i></i>'.repeat(13)}</div></div>${button(icon('pause'),'stop-speaking','icon-button','aria-label="Зупинити демонстрацію озвучення"')}</div>`;
 if(s==='correct')html+=`<article class="correction correct" role="status">${avatar('success','medium')}<div><span class="eyebrow">${icon('check')}ГАРНА ВІДПОВІДЬ</span><h2 lang="${demo.target}">${w.good}</h2><p>Саме так. Ти правильно узгодив / узгодила дієслово з підметом.</p><small>Приклад feedback, не оцінка твоєї відповіді AI.</small></div></article>`;
 if(s==='incorrect')html+=`<article class="correction incorrect" role="status">${avatar('encourage','medium')}<div><span class="eyebrow">СПРОБУЙМО ЩЕ РАЗОМ</span><p lang="${demo.target}"><del>${w.bad}</del></p><h2 lang="${demo.target}">${w.good}</h2><p>Сенс зрозумілий. Після «я» потрібна форма дієслова першої особи.</p><small>Це заготовлений навчальний приклад.</small></div></article>`;
 if(s==='offline'||s==='api-error')html+=`<section class="error-card" role="alert">${icon(s==='offline'?'wifi':'alert')}<div><h2>${s==='offline'?'Зараз немає з’єднання':'Не вдалося отримати відповідь'}</h2><p>${s==='offline'?'Історія залишається видимою. Для справжньої AI-розмови потрібен інтернет.':'Спробуй повторити запит трохи пізніше. Твій текст не зникає.'}</p><small>Демонстраційний стан. Жодного API-запиту не виконано.</small>${button('Спробувати ще раз','retry','button secondary')}</div></section>`;
 }
 html+=demo.messages.map(m=>message(m.text,m.who)).join('');return html;}
function chat(){const blocked=['thinking','offline','api-error'].includes(demo.chatState);return `<main class="chat-screen" id="mainContent" tabindex="-1"><header class="chat-header">${go('home',icon('back'),'icon-button')}${avatar(stateEmotion[demo.chatState],'small')}<div class="chat-person"><b>Lexi</b><span class="chat-status" role="status">${stateText[demo.chatState]}</span></div><div class="chat-header-actions">${button(icon('sound'),'voice-toggle','icon-button',`aria-label="${demo.voice?'Вимкнути':'Увімкнути'} озвучення (демо)" aria-pressed="${demo.voice}"`)}${themeButton()}</div></header><div class="chat-layout"><aside class="chat-sidebar"><div class="chat-config">${targetSelect('chatTarget')}${levelSelect()}</div><div class="scenario-heading"><span class="eyebrow">КОРОТКІ СЦЕНАРІЇ</span><h2>З чого почнемо?</h2></div>${scenarios()}<div class="chat-privacy">${icon('chat')}<p>Один Lexi для всіх AI-розмов.</p><small>Mock-дані. Без мікрофона, API й збереження повідомлень.</small></div></aside><div class="chat-workspace"><div class="state-review"><label>Огляд стану<select id="stateControl" data-select="chat-state">${chatStates.map(s=>`<option value="${s}" ${demo.chatState===s?'selected':''}>${statesLabels[s]}</option>`).join('')}</select></label><span>${demo.scenario}</span></div><div class="chat-log" aria-label="Історія демонстраційної розмови" aria-busy="${demo.chatState==='thinking'}">${chatBody()}</div><form class="composer" id="composer"><label class="sr-only" for="messageInput">Повідомлення Lexi</label><textarea id="messageInput" rows="2" placeholder="Напиши Lexi…" maxlength="1000" ${blocked?'disabled':''}>${esc(demo.draft)}</textarea><div class="compose-bottom">${button(icon('mic'),demo.chatState==='listening'?'stop-listening':'listen-demo','icon-button mic-button',`aria-label="${demo.chatState==='listening'?'Завершити':'Показати'} прослуховування (демо)" aria-pressed="${demo.chatState==='listening'}" ${blocked?'disabled':''}`)}<span>Enter — надіслати<br>Shift + Enter — новий рядок</span><button type="submit" class="send-button" aria-label="Надіслати демонстраційне повідомлення" ${blocked?'disabled':''}>${icon('send')}</button></div><p class="composer-note">Демо: відповідь заготовлена. Це не справжня AI-перевірка.</p></form></div></div></main>`}
function lessonHeader(title,count){return `<header class="lesson-header">${go('home',icon('close'),'icon-button')}<div><b>${title}</b><div class="lesson-track"><i></i></div></div><span>${count}</span>${themeButton()}</header>`}
function listenButton(label='Послухати вимову',cls=''){return button(icon(demo.playing?'pause':'sound')+`<span>${demo.playing?'Відтворення · демо':label}</span>`,'audio-demo','sound-button '+cls,`aria-pressed="${demo.playing}" aria-label="${label} — демонстрація стану"`)}
function lessonFooter(label,screen){return `<footer class="lesson-footer"><p>${icon('headphones')}Послухай. Повтори. Скажи самостійно.</p>${go(screen,label+' '+icon('arrow'),'button primary')}</footer>`}
function study(){const w=current();return `<main class="lesson-screen" id="mainContent" tabindex="-1">${lessonHeader('Знайомство','1 / 5')}<div class="lesson-content study"><div class="lesson-kicker"><span class="eyebrow">ВИВЧИ НОВЕ СЛОВО</span><span>${names[demo.target]} · ${demo.level}</span></div><section class="word-card"><div class="word-guide">${avatar('speaking','medium')}<span>Почнімо з простого.</span></div><p class="word-label">Слово 1 із 5</p><h1 lang="${demo.target}">${w.word}</h1><p class="word-translation">привіт</p>${listenButton()}</section><section class="sentence-card"><span class="eyebrow">У РЕАЛЬНІЙ РОЗМОВІ</span><p lang="${demo.target}">${w.example}</p><p>${w.meaning}</p></section>${lessonFooter('Зрозуміло, далі','quiz')}</div></main>`}
function answers(list,action){return `<div class="answers">${list.map((text,i)=>`<button type="button" data-action="${action}" data-answer="${i}" class="answer ${demo.selected===i?'selected':''} ${demo.checked&&(i===1?'correct':demo.selected===i?'wrong':'')}" ${demo.checked?'disabled':''}><span class="answer-number">${String(i+1).padStart(2,'0')}</span><span lang="${action==='choose-answer'?demo.target:'uk'}">${text}</span><span class="answer-result" aria-hidden="true">${demo.checked?(i===1?'✓':demo.selected===i?'×':''):''}</span></button>`).join('')}</div>`}
function quiz(){const w=current(),ok=demo.selected===1;return `<main class="lesson-screen" id="mainContent" tabindex="-1">${lessonHeader('Перевір себе','2 / 5')}<div class="lesson-content quiz"><div class="quiz-prompt"><div><span class="eyebrow">ОБЕРИ ПЕРЕКЛАД</span><h1>Як сказати<br><em>«привіт»?</em></h1></div>${avatar(demo.checked?(ok?'success':'encourage'):'thinking','medium')}</div>${answers(w.options,'choose-answer')}<div class="quiz-footer"><div class="quiz-feedback ${demo.checked?(ok?'success':'error'):''}" role="status" aria-live="polite">${demo.checked?icon(ok?'check':'repeat')+`<div><b>${ok?'Саме так!':'Запам’ятай правильну відповідь'}</b><p lang="${demo.target}">${w.word} — привіт</p></div>`:'Обери одну відповідь.'}</div>${button((demo.checked?'Далі':'Перевірити')+' '+icon('arrow'),'check-answer','button primary',demo.selected===null?'disabled':'')}</div></div></main>`}
function audio(){return `<main class="lesson-screen" id="mainContent" tabindex="-1">${lessonHeader('Послухай і зрозумій','2 / 5')}<div class="lesson-content audio"><span class="eyebrow">АУДІЮВАННЯ</span><h1>Спочатку послухай.<br>Потім обери.</h1><section class="audio-stage">${avatar('listening','large')}${listenButton('Відтворити фразу','large')}<div class="voice-wave ${demo.playing?'playing':''}" aria-hidden="true">${'<i></i>'.repeat(21)}</div><p>Огляд стану аудіоплеєра. Звук не підключено.</p></section>${answers(['дякую','привіт','до завтра'],'choose-audio')}<div class="quiz-feedback" role="status">${demo.checked?'Демонстрація: правильна відповідь — «привіт».':''}</div>${go('review','До повторення '+icon('arrow'),'button primary')}</div></main>`}
function review(){return `<main class="lesson-screen" id="mainContent" tabindex="-1">${lessonHeader('Повторення складних слів','1 / 3')}<div class="lesson-content review"><div class="review-heading"><div><span class="eyebrow">ПОВТОРЕННЯ БЕЗ ПОСПІХУ</span><h1>Знайоме слово.<br>Нова впевненість.</h1></div>${avatar('encourage','medium')}</div><section class="review-card"><span class="tag">СЛОВО, ЯКЕ ВАРТО ПОВТОРИТИ</span><h2 lang="${demo.target}">${current().word}</h2>${listenButton()}<p>${demo.reviewOpen?'привіт':'Згадай переклад перед тим, як відкрити відповідь.'}</p>${demo.reviewOpen?`<p lang="${demo.target}">${current().example}</p>`:button('Показати відповідь','reveal','button secondary')}</section><div class="review-actions">${button(icon('repeat')+'Ще повторю','review-again','button secondary')}${button(icon('check')+'Згадав / згадала','review-success','button primary')}</div><p class="data-note">Демонстрація Review. SRS і прогрес не підключені.</p></div></main>`}
function life(){return `<main class="life-screen" id="mainContent" tabindex="-1"><div class="life-scene"><img src="assets/life-station-proposal.webp" alt="Концепт-ілюстрація: Anastasia та Annick на вокзалі, статична сцена" width="960" height="1440"></div><header class="life-header">${go('home',icon('back'),'icon-button')}<div><span class="eyebrow">LERENBE LIFE · НІДЕРЛАНДСЬКА</span><b>Gent-Sint-Pieters</b></div><span>2 / 8</span>${themeButton()}</header><div class="life-progress" role="progressbar" aria-label="Демонстраційний крок історії" aria-valuenow="2" aria-valuemin="0" aria-valuemax="8"><i></i></div><span class="art-note">ІЛЮСТРАЦІЯ-ПРОПОЗИЦІЯ · СЦЕНА ДЕМО</span><section class="dialogue-card"><div class="life-speaker"><span class="human-avatar">A</span><div><b>Annick</b><span>Твоя співрозмовниця</span></div>${listenButton('Послухати')}</div><h1 lang="nl">Hallo! Ben jij Anastasia?</h1><p>Привіт! Ти Анастасія?</p><div class="reply-heading"><b>Твоя відповідь</b><span>Обери фразу</span></div><div class="life-replies">${[['Ja, ik ben Anastasia.','Так, я Анастасія.'],['Nee, ik woon in Gent.','Ні, я живу в Генті.']].map(([nl,uk],i)=>button(`<span lang="nl">${nl}</span><small>${uk}</small>${icon('arrow')}`,'life-answer',`life-answer ${demo.lifeReply===i?(i===0?'correct':'wrong'):''}`,`data-answer="${i}"`)).join('')}</div><p class="life-result" role="status">${demo.lifeReply===null?'':demo.lifeReply===0?'Добре! Так починається знайомство. (Демо)':'Запитання про ім’я. Спробуй: Ja, ik ben Anastasia. (Демо)'}</p></section></main>`}
let timeout,toastTimer;const app=document.getElementById('app');
function url(){history.replaceState(null,'',`?screen=${demo.screen}&theme=${demo.theme}&state=${demo.chatState}&target=${demo.target}&level=${demo.level}`)}
function render(){const active=document.activeElement;const focusKey=active?.dataset.action?`[data-action="${active.dataset.action}"]${active.dataset.answer!==undefined?`[data-answer="${active.dataset.answer}"]`:''}`:active?.dataset.select?`[data-select="${active.dataset.select}"]`:null;document.documentElement.dataset.theme=demo.theme;document.title=`LerenBe · ${demo.screen==='chat'?'Lexi':demo.screen} · TEST-030 Demo`;app.dataset.screen=demo.screen;app.innerHTML=({home,chat,study,quiz,audio,review,life}[demo.screen])();url();if(focusKey)app.querySelector(focusKey)?.focus({preventScroll:true})}
function notify(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3500)}
function navigate(s){clearTimeout(timeout);demo.screen=s;demo.selected=null;demo.checked=false;demo.playing=false;render();window.scrollTo(0,0);document.querySelector('#mainContent')?.focus({preventScroll:true})}
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='navigate')return navigate(b.dataset.screen);
 if(a==='theme'){demo.theme=demo.theme==='dark'?'light':'dark';const input=document.getElementById('messageInput')?.value;render();if(input&&document.getElementById('messageInput'))document.getElementById('messageInput').value=input;return}
 if(a==='scenario'){demo.scenario=b.dataset.scenario;demo.chatState='welcome';demo.messages=[];render();return}
 if(a==='listen-demo'||a==='stop-listening'){clearTimeout(timeout);demo.chatState=a==='listen-demo'?'listening':'welcome';render();return}
 if(a==='voice-toggle'){demo.voice=!demo.voice;b.setAttribute('aria-pressed',String(demo.voice));b.setAttribute('aria-label',(demo.voice?'Вимкнути':'Увімкнути')+' озвучення (демо)');notify('Демонстраційне налаштування. Звук не підключено.');return}
 if(a==='speak-demo'){demo.chatState='speaking';render();return}
 if(a==='stop-speaking'){demo.chatState='welcome';render();return}
 if(a==='retry'){demo.chatState='thinking';render();timeout=setTimeout(()=>{demo.chatState='welcome';render()},900);return}
 if(a==='choose-answer'){demo.selected=+b.dataset.answer;render();return}
 if(a==='check-answer'){if(demo.checked)return navigate('audio');demo.checked=true;render();document.querySelector('.quiz-footer .primary')?.focus();return}
 if(a==='choose-audio'){demo.selected=+b.dataset.answer;demo.checked=true;render();return}
 if(a==='audio-demo'){demo.playing=!demo.playing;render();notify('Демо стану плеєра. Мікрофон та озвучення не підключені.');clearTimeout(timeout);if(demo.playing)timeout=setTimeout(()=>{demo.playing=false;render()},1800);return}
 if(a==='reveal'){demo.reviewOpen=true;render();return}
 if(a==='review-success'||a==='review-again'){notify(a==='review-success'?'Демо успіху. Результат не зберігається.':'Демо повторення. SRS не змінюється.');return}
 if(a==='life-answer'){demo.lifeReply=+b.dataset.answer;render();return}
});
app.addEventListener('change',e=>{const type=e.target.dataset.select;if(type==='target'){demo.target=e.target.value;demo.messages=[];demo.chatState='welcome';render()}if(type==='level'){demo.level=e.target.value;render()}if(type==='chat-state'){clearTimeout(timeout);demo.chatState=e.target.value;demo.messages=[];render()}});
app.addEventListener('input',e=>{if(e.target.id==='messageInput')demo.draft=e.target.value});
function send(){const input=document.getElementById('messageInput'),text=input?.value.trim();if(!text)return;demo.draft='';demo.messages.push({who:'user',text});demo.chatState='thinking';render();clearTimeout(timeout);timeout=setTimeout(()=>{demo.chatState='welcome';demo.messages.push({who:'lexi',text:'Демо-відповідь: гарний початок! У справжньому чаті тут буде відповідь Lexi на твій запит. Спробуй коротке речення про свій день.'});render();document.getElementById('messageInput')?.focus();document.querySelector('.chat-log')?.scrollTo({top:99999})},950)}
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='composer')send()});app.addEventListener('keydown',e=>{if(e.target.id==='messageInput'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send()}});
render();
